command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/f5-f6-semantics-20261006"
$baseline="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$candidate="37cb86dc6fe55ac71a0fb9f30b0d1f1a86a01c04"
$temp=Join-Path $env:RUNNER_TEMP ("f5-f6-standard-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before F5/F6 validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before F5/F6 validation: $branchSha"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_shortcut_semantics_contract.py tests\winui\test_m21_gui.py
  if($LASTEXITCODE -ne 0){throw "shortcut Python static check failed"}

  & python -X utf8 -m unittest tests.winui.test_shortcut_semantics_contract
  if($LASTEXITCODE -ne 0){throw "shortcut source contract failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $baseline --head $candidate
  if($LASTEXITCODE -ne 0){throw "FAST validation failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "Release build failed"}

  & python -X utf8 tools\winui\run_checks.py gui --area file-operations --configuration Release
  if($LASTEXITCODE -ne 0){throw "focused file-operations GUI failed"}

  Write-Host ("F5_F6_CANDIDATE="+$candidate)
  Write-Host "F5_F6_SEMANTICS_STANDARD=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
